import "forge-std/Test.sol";

contract VotingEscrowTest is Test {
    VotingEscrow public votingEscrow;

    function setUp() public {
        votingEscrow = new VotingEscrow();
    }

    function testReentrancyGuard() public {
        // Attempt to call vulnerable functions recursively
        votingEscrow.create_lock(...);
        votingEscrow.increase_amount(...);
        votingEscrow.increase_unlock_time(...);
        votingEscrow.withdraw(...);

        // Assert that reentrancy guard prevents recursive calls
        assertEq(votingEscrow._reentrancyGuard, false);
    }
}

